import{silverCampLayout,SILVER_MAP,outsideFootprint}from'./silver-camps.mjs';
import{spawnDefinition}from'./silver-monsters.mjs';
import{CONTENT}from'./data.mjs';
import{petStats}from'./rules.mjs';
export function campActor(slot,campId,clock,active,generation=0){const d=spawnDefinition(slot.type,SILVER_MAP),petType=CONTENT.pets.find(p=>p.wild_monster_id===slot.type)?.id;const a={id:'silver-slot-'+slot.id+'-g'+generation,generation,type:d.id,...(d.profile_id?{definitionProfile:d.profile_id}:{}),populationId:'POP-SILVER-CAMP-'+slot.type.slice(4),slot:0,campId,campSlotId:slot.id,x:slot.x,y:slot.y,origin:{x:slot.x,y:slot.y},hp:active?d.hp:0,mp:d.mp,maxHp:d.hp,level:d.level,effects:[],attackAt:clock,moveAt:clock,nextAI:clock+250,path:[],targetId:null,respawnAt:active?null:clock,deadAt:active?null:clock,lootDone:!active,weaponDurability:null,healingPotions:0};if(petType){a.petType=petType;a.aptitudes={hp:100,attack:100,defense:100,speed:100};a.maxHp=petStats({...a,type:petType}).maxHp;a.hp=active?a.maxHp:0;}return a;}
export function initializeSilverCamps(s,{initial=false}={}){const w=s.worlds[SILVER_MAP];if(!w||w.campRevision===1)return false;const layout=silverCampLayout();w.campRevision=1;w.campCycles={};for(const c of layout.camps){w.campCycles[c.id]={cleared:!initial};for(const slot of c.slots)w.monsters.push(campActor(slot,c.id,s.clockMs,initial));}return true;}
export function refreshSilverCamps(s){const w=s.worlds[SILVER_MAP];if(!w||s.player.map!==SILVER_MAP||w.campRevision!==1)return;for(const c of silverCampLayout().camps){const rows=w.monsters.filter(m=>m.campId===c.id),cycle=w.campCycles[c.id];if(rows.every(m=>m.hp<=0||m.captured))cycle.cleared=true;if(!cycle.cleared||!outsideFootprint(s.player,c))continue;for(const slot of c.slots){const i=w.monsters.findIndex(m=>m.campSlotId===slot.id),m=w.monsters[i];if(m.hp>0||(m.captured&&m.respawnAt===null)||m.respawnAt===null||m.respawnAt>s.clockMs)continue;const next=campActor(slot,c.id,s.clockMs,true,(m.generation||0)+1);w.monsters[i]=next;}if(w.monsters.filter(m=>m.campId===c.id).every(m=>m.hp>0||m.captured))cycle.cleared=false;}}
export function prepareSilverMigration(state){if(state.monsterRevision===1)return null;const next=structuredClone(state);next.monsterRevision=1;initializeSilverCamps(next);return{state:next,notice:'已保留升級前原始存檔；舊活怪數值維持原版，新營地在離開視野後才補入。'};}
